class MainActivity:ComponentActivity(){
 override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);setContent{TitanTheme{TitanApp()}}}
}
private enum class Screen{WELCOME,OBJECTIVE,PROFILE,PROFESSION,WORK,WORK_DETAIL,TRAINING,MEAL_COUNT,MAINTENANCE,STRATEGY,TODAY,MEALS,DISH,ALTERNATIVES,INGREDIENT,DAY_CLOSE,WEEK,WEEK_REVIEW,BODY,ADD,SOCIAL}

@Composable fun TitanApp(){
 val context=LocalContext.current
 val store=remember{TitanStore(context)}
 val saved=remember{runCatching{store.load()}.getOrNull()}
 var screen by remember{mutableStateOf(Screen.WELCOME)}
 var sex by remember{mutableStateOf(saved?.sex?:Sex.MALE)}
 var age by remember{mutableStateOf((saved?.age?:39).toString())};var height by remember{mutableStateOf((saved?.heightCm?:170.0).toInt().toString())};var weight by remember{mutableStateOf((saved?.weightKg?:93.0).toInt().toString())}
 var profession by remember{mutableStateOf(TITAN_PROFESSIONS.first())}
 var standing by remember{mutableStateOf("7")};var moving by remember{mutableStateOf("5")};var load by remember{mutableStateOf("2")};var breaks by remember{mutableStateOf("1")};var workIntensity by remember{mutableStateOf(WorkIntensity.MODERATE)};var variableDay by remember{mutableStateOf(true)}
 var sessions by remember{mutableStateOf("4")};var minutes by remember{mutableStateOf("75")};var trainingIntensity by remember{mutableStateOf(TrainingIntensity.HIGH)};var mealCount by remember{mutableStateOf(saved?.mealCount?:4)}
 var estimate by remember{mutableStateOf<EnergyEstimate?>(saved?.let{EnergyEstimate(0,0,0,0,it.maintenance)})};var strategy by remember{mutableStateOf(saved?.strategy?:Strategy.MODERATE)}
 var selectedMealId by remember{mutableStateOf<String?>(null)};var proposedDish by remember{mutableStateOf<Dish?>(null)};var selectedIngredient by remember{mutableStateOf(0)}
 var meals by remember{mutableStateOf(saved?.let{
  runCatching{
   val base=TitanEngine.plans(it.maintenance).first{p->p.strategy==it.strategy}
   store.ensureToday(base.copy(target=store.activeTarget(base.target))).meals
  }.getOrElse{
   store.clear()
   emptyList()
  }
 }?:emptyList())}
 fun currentPlan():CaloriePlan{val m=estimate?.maintenance?:1;val base=TitanEngine.plans(m).first{it.strategy==strategy};val target=store.activeTarget(base.target);return base.copy(target=target)}
 Surface(Modifier.fillMaxSize(),color=TitanBackground){
  Box(Modifier.fillMaxSize().background(Brush.verticalGradient(listOf(TitanBackground,Color(0xFF0C1821),TitanBackground)))){
  AnimatedContent(targetState=screen,transitionSpec={fadeIn(tween(260))+slideInHorizontally(tween(260)){it/10} togetherWith fadeOut(tween(180))},label="screen"){shownScreen->
  Box(Modifier.fillMaxSize().windowInsetsPadding(WindowInsets.navigationBars)){TitanAtmosphere();
  when(shownScreen){
   Screen.WELCOME->Welcome{screen=if(saved!=null)Screen.TODAY else Screen.OBJECTIVE}
   Screen.OBJECTIVE->Objective{screen=Screen.PROFILE}
   Screen.PROFILE->Profile(age,{age=it},height,{height=it},weight,{weight=it},sex,{sex=it}){screen=Screen.PROFESSION}
   Screen.PROFESSION->ProfessionQuestion(profession,{profession=it}){screen=Screen.WORK}
   Screen.WORK->Work(standing,{standing=it},moving,{moving=it},load,{load=it}){screen=Screen.WORK_DETAIL}
   Screen.WORK_DETAIL->WorkDetail(breaks,{breaks=it},workIntensity,{workIntensity=it},variableDay,{variableDay=it}){screen=Screen.TRAINING}
   Screen.TRAINING->Training(sessions,{sessions=it},minutes,{minutes=it},trainingIntensity,{trainingIntensity=it}){
    val w=weight.toDoubleOrNull()?:70.0
    val qe=QuestionnaireEngine.energy(w,ActivityQuestionnaire(standing.toDoubleOrNull()?:0.0,moving.toDoubleOrNull()?:0.0,load.toDoubleOrNull()?:0.0,workIntensity,breaks.toDoubleOrNull()?:0.0,variableDay,profession),TrainingQuestionnaire(sessions.toIntOrNull()?:0,minutes.toIntOrNull()?:0,trainingIntensity))
    estimate=TitanEngine.estimateEnergy(UserProfile(sex,age.toIntOrNull()?:30,height.toDoubleOrNull()?:170.0,w,1.2,qe.workDailyKcal,qe.trainingDailyKcal));screen=Screen.MEAL_COUNT
   }
   Screen.MEAL_COUNT->MealCountQuestion(mealCount,{mealCount=it}){screen=Screen.MAINTENANCE}
   Screen.MAINTENANCE->Maintenance(estimate!!){screen=Screen.STRATEGY}
   Screen.STRATEGY->Strategies(estimate!!.maintenance,strategy,{strategy=it}){
    val profile=UserProfile(sex,age.toIntOrNull()?:30,height.toDoubleOrNull()?:170.0,weight.toDoubleOrNull()?:70.0)
    store.save(profile,estimate!!.maintenance,strategy,mealCount)
    val names=mealNamesForCount(mealCount);meals=TitanEngine.distribute(currentPlan().target,names);store.saveDay(meals,currentPlan());screen=Screen.TODAY}
   Screen.TODAY->{val p=currentPlan();Today(p,TitanEngine.balance(p,meals.sumOf{it.consumedKcal}),MealEngine.macroBalance(MealEngine.macroTarget(weight.toDoubleOrNull()?:70.0,p.target),meals),meals,{screen=Screen.MEALS},{id->val updated=meals.map{if(it.id==id)it.copy(status=MealStatus.SKIPPED)else it}.let(TitanEngine::redistribute);meals=updated;store.saveDay(updated,p)},{screen=Screen.DAY_CLOSE},{screen=Screen.WEEK},{screen=Screen.ADD},{screen=Screen.SOCIAL})}
   Screen.MEALS->MealList(meals,{m->selectedMealId=m.id;proposedDish=MealEngine.propose(m.plannedKcal);screen=Screen.DISH},{id->val updated=meals.map{if(it.id==id)it.copy(status=MealStatus.SKIPPED)else it}.let(TitanEngine::redistribute);meals=updated;store.saveDay(updated,currentPlan())},{screen=Screen.TODAY})
   Screen.DISH->DishProposal(proposedDish!!,{screen=Screen.ALTERNATIVES},{index->selectedIngredient=index;screen=Screen.INGREDIENT},{
    val id=selectedMealId;val d=proposedDish!!;val updated=meals.map{if(it.id==id)it.copy(name=d.name,consumedKcal=d.kcal,status=MealStatus.CONFIRMED,proteinG=d.proteinG,carbsG=d.carbsG,fatG=d.fatG)else it}.let(TitanEngine::redistribute);meals=updated;store.saveDay(updated,currentPlan());screen=Screen.MEALS
   },{screen=Screen.MEALS})
   Screen.ALTERNATIVES->Alternatives(meals.first{it.id==selectedMealId}.plannedKcal,proposedDish!!,{d->proposedDish=d;screen=Screen.DISH},{screen=Screen.DISH})
   Screen.INGREDIENT->IngredientEditor(proposedDish!!,selectedIngredient,{g->proposedDish=MealEngine.resizeIngredient(proposedDish!!,selectedIngredient,g)},{replacement->proposedDish=MealEngine.replaceIngredient(proposedDish!!,selectedIngredient,replacement);screen=Screen.DISH},{screen=Screen.DISH})
   Screen.DAY_CLOSE->DayClose(TitanEngine.closeDay(currentPlan(),meals),store.remainingDaysInWeek()){store.saveDay(meals,currentPlan(),closed=true);screen=Screen.WEEK}
   Screen.WEEK->WeekHistory(store.weekHistory(),{screen=Screen.WEEK_REVIEW},{screen=Screen.BODY}){screen=Screen.TODAY}
   Screen.BODY->BodyProgress(store.bodyHistory(),{w,waist->store.saveBodyEntry(w,waist)},{screen=Screen.TODAY})
   Screen.WEEK_REVIEW->WeeklyReviewScreen(store.weekHistory(),currentPlan().target,{adjustment->store.applyWeeklyAdjustment(adjustment);val names=mealNamesForCount(mealCount);meals=TitanEngine.distribute(adjustment.nextTarget,names);store.saveDay(meals,currentPlan());screen=Screen.TODAY},{screen=Screen.TODAY})
   Screen.SOCIAL->SocialMealScreen({name,kcal->val updated=meals+MealSlot("social-"+System.currentTimeMillis(),name,kcal,kcal,MealStatus.CONFIRMED);meals=updated;store.saveDay(updated,currentPlan());screen=Screen.TODAY},{screen=Screen.TODAY})
   Screen.ADD->AddMeal({n,k->val i=meals.indexOfFirst{it.status==MealStatus.PENDING};if(i>=0){val updated=meals.mapIndexed{x,m->if(x==i)m.copy(name=n,consumedKcal=k,status=MealStatus.CONFIRMED)else m}.let(TitanEngine::redistribute);meals=updated;store.saveDay(updated,currentPlan())};screen=Screen.TODAY}){screen=Screen.TODAY}
  }
  if(shownScreen!=Screen.WELCOME){TitanArrows(shownScreen,{screen=previousScreen(shownScreen)},{screen=nextScreen(shownScreen)})}
  }}
  }
 }
}
private fun previousScreen(s:Screen)=when(s){Screen.OBJECTIVE->Screen.WELCOME;Screen.PROFILE->Screen.OBJECTIVE;Screen.PROFESSION->Screen.PROFILE;Screen.WORK->Screen.PROFESSION;Screen.WORK_DETAIL->Screen.WORK;Screen.TRAINING->Screen.WORK_DETAIL;Screen.MEAL_COUNT->Screen.TRAINING;Screen.MAINTENANCE->Screen.MEAL_COUNT;Screen.STRATEGY->Screen.MAINTENANCE;Screen.TODAY->Screen.TODAY;Screen.MEALS->Screen.TODAY;Screen.DISH->Screen.MEALS;Screen.ALTERNATIVES->Screen.DISH;Screen.INGREDIENT->Screen.DISH;Screen.DAY_CLOSE->Screen.TODAY;Screen.WEEK->Screen.TODAY;Screen.WEEK_REVIEW->Screen.WEEK;Screen.BODY->Screen.WEEK;Screen.ADD->Screen.TODAY;Screen.SOCIAL->Screen.ADD;else->s}
private fun nextScreen(s:Screen)=when(s){Screen.TODAY->Screen.MEALS;Screen.MEALS->Screen.ADD;Screen.ADD->Screen.SOCIAL;Screen.WEEK->Screen.BODY;else->s}
@Composable private fun TitanArrows(s:Screen,back:()->Unit,next:()->Unit){Row(Modifier.fillMaxWidth().padding(horizontal=18.dp,vertical=12.dp),horizontalArrangement=Arrangement.SpaceBetween){Text("‹",fontSize=38.sp,color=TitanText,modifier=Modifier.clickable{back()}.padding(8.dp));val n=nextScreen(s);Text("›",fontSize=38.sp,color=if(n!=s)TitanPrimary else TitanDivider,modifier=Modifier.clickable(enabled=n!=s){next()}.padding(8.dp))}}
@Composable private fun TitanAtmosphere(){Canvas(Modifier.fillMaxSize()){val h=size.height;val w=size.width;drawCircle(Color(0x162ED4B7),w*.72f,Offset(w*.88f,h*.10f));drawCircle(Color(0x0D57C7E6),w*.92f,Offset(w*.08f,h*.55f));val far=Path().apply{moveTo(0f,h*.88f);lineTo(w*.17f,h*.77f);lineTo(w*.31f,h*.86f);lineTo(w*.52f,h*.69f);lineTo(w*.72f,h*.84f);lineTo(w*.90f,h*.73f);lineTo(w,h*.80f);lineTo(w,h);lineTo(0f,h);close()};drawPath(far,Color(0x152A3943));val near=Path().apply{moveTo(0f,h*.94f);lineTo(w*.22f,h*.82f);lineTo(w*.38f,h*.91f);lineTo(w*.61f,h*.76f);lineTo(w*.79f,h*.89f);lineTo(w,h*.81f);lineTo(w,h);lineTo(0f,h);close()};drawPath(near,Color(0x24202D35));drawLine(TitanPrimary.copy(alpha=.12f),Offset(w*.52f,h*.69f),Offset(w*.61f,h*.76f),2f)}}
@Composable private fun TitanMark(){Image(painter=painterResource(R.drawable.titan_mark_official),contentDescription="TITÁN",modifier=Modifier.width(154.dp).height(100.dp),contentScale=ContentScale.Fit)}
@Composable private fun FoodVisual(modifier:Modifier=Modifier){Canvas(modifier.clip(RoundedCornerShape(18.dp)).background(Brush.linearGradient(listOf(Color(0xFF25323A),Color(0xFF0D151B))))){val w=size.width;val h=size.height;drawCircle(Color(0xFF11191E),w*.36f,Offset(w*.50f,h*.52f));drawCircle(Color(0xFFD9C49A),w*.26f,Offset(w*.50f,h*.52f));drawCircle(Color(0xFF4CAF7A),w*.11f,Offset(w*.39f,h*.43f));drawCircle(Color(0xFFE6B85C),w*.10f,Offset(w*.60f,h*.43f));drawCircle(Color(0xFFB66D52),w*.11f,Offset(w*.48f,h*.62f));drawCircle(Color(0xFFF1E3C6),w*.08f,Offset(w*.64f,h*.61f));drawCircle(TitanPrimary.copy(alpha=.16f),w*.55f,Offset(w*.5f,h*.5f))}}
@Composable private fun Welcome(next:()->Unit){Box(Modifier.fillMaxSize().clickable{next()}){Image(painter=painterResource(R.drawable.titan_welcome),contentDescription="Bienvenida TITÁN",modifier=Modifier.fillMaxSize(),contentScale=ContentScale.Crop)}}
