@Composable private fun Field(label:String,value:String,set:(String)->Unit){OutlinedTextField(value,{set(it.filter(Char::isDigit))},label={Text(label)},modifier=Modifier.fillMaxWidth().padding(vertical=5.dp),colors=OutlinedTextFieldDefaults.colors(focusedBorderColor=TitanPrimary,unfocusedBorderColor=TitanDivider))}
@Composable private fun TextFieldInput(label:String,value:String,set:(String)->Unit){OutlinedTextField(value,set,label={Text(label)},modifier=Modifier.fillMaxWidth().padding(vertical=5.dp),colors=OutlinedTextFieldDefaults.colors(focusedBorderColor=TitanPrimary,unfocusedBorderColor=TitanDivider))}
@Composable private fun PrimaryButton(label:String,go:()->Unit){Button(go,Modifier.fillMaxWidth().height(56.dp),shape=RoundedCornerShape(16.dp),colors=ButtonDefaults.buttonColors(containerColor=TitanPrimary,contentColor=TitanBackground),elevation=ButtonDefaults.buttonElevation(defaultElevation=7.dp,pressedElevation=2.dp)){Text(label.uppercase(),fontWeight=FontWeight.ExtraBold,letterSpacing=.8.sp)}}
@Composable private fun Objective(next:()->Unit){var selected by remember{mutableStateOf("Recomposición corporal")};val options=listOf("Recomposición corporal" to "Perder grasa y construir una versión más fuerte de ti.","Rendimiento deportivo" to "Alimenta el entrenamiento y mejora tu rendimiento.","Salud y bienestar" to "Construye hábitos sostenibles para sentirte mejor.","Otro objetivo" to "Configura TITÁN alrededor de una prioridad diferente.");Column(Modifier.padding(horizontal=24.dp)){Header("Paso 1 de 8","¿Cuál es tu objetivo principal?");Text("Selecciona el que mejor se adapta a ti en este momento.",color=TitanTextSecondary);Spacer(Modifier.height(14.dp));options.forEach{(title,desc)->Card(onClick={selected=title},modifier=Modifier.fillMaxWidth().padding(vertical=6.dp),shape=RoundedCornerShape(20.dp),colors=CardDefaults.cardColors(containerColor=if(selected==title)TitanPrimary.copy(alpha=.13f) else TitanCard),border=if(selected==title)androidx.compose.foundation.BorderStroke(1.dp,TitanPrimary) else null){Row(Modifier.padding(17.dp),verticalAlignment=Alignment.CenterVertically){Column(Modifier.weight(1f)){Text(title.uppercase(),fontWeight=FontWeight.ExtraBold);Text(desc,color=TitanTextSecondary,fontSize=12.sp)};Text(if(selected==title)"✓" else "○",color=if(selected==title)TitanPrimary else TitanTextSecondary,fontSize=22.sp)}}};Spacer(Modifier.weight(1f));PrimaryButton("CONTINUAR",next)}}
@Composable private fun Profile(age:String,setAge:(String)->Unit,height:String,setHeight:(String)->Unit,weightValue:String,setWeight:(String)->Unit,sex:Sex,setSex:(Sex)->Unit,next:()->Unit){Column(Modifier.padding(24.dp)){Header("Paso 2 de 8","Tus datos");Row{FilterChip(sex==Sex.MALE,{setSex(Sex.MALE)},{Text("Hombre")});Spacer(Modifier.width(8.dp));FilterChip(sex==Sex.FEMALE,{setSex(Sex.FEMALE)},{Text("Mujer")})};Field("Edad",age,setAge);Field("Altura (cm)",height,setHeight);Field("Peso (kg)",weightValue,setWeight);Spacer(Modifier.weight(1f));PrimaryButton("Continuar",next)}}
@Composable private fun ProfessionQuestion(selected:Profession,setSelected:(Profession)->Unit,next:()->Unit){var open by remember{mutableStateOf(false)};var query by remember{mutableStateOf("")};Column(Modifier.padding(24.dp)){Header("Paso 3 de 8","¿A qué te dedicas?");Text("Selecciona la profesión que más se aproxime a tu trabajo habitual.",color=TitanTextSecondary);Spacer(Modifier.height(16.dp));Card(onClick={open=true},modifier=Modifier.fillMaxWidth(),shape=RoundedCornerShape(18.dp),colors=CardDefaults.cardColors(containerColor=TitanCard)){Row(Modifier.fillMaxWidth().padding(18.dp)){Text(selected.name,Modifier.weight(1f),fontWeight=FontWeight.Bold);Text("⌄",color=TitanPrimary)}};Text("TITÁN cruzará esta referencia con cómo es realmente tu jornada.",color=TitanTextSecondary,fontSize=12.sp,modifier=Modifier.padding(top=10.dp));Spacer(Modifier.weight(1f));PrimaryButton("Continuar",next)};if(open){AlertDialog(onDismissRequest={open=false},title={Text("Buscar profesión")},text={Column{TextFieldInput("Profesión o aproximación",query){query=it};Spacer(Modifier.height(8.dp));val results=TITAN_PROFESSIONS.filter{query.isBlank()||it.name.contains(query,true)}.take(8);if(results.isEmpty())Text("No hay coincidencias. Busca una profesión aproximada.",color=TitanTextSecondary) else results.forEach{p->Surface(shape=RoundedCornerShape(12.dp),color=if(p.id==selected.id)TitanPrimary.copy(alpha=.12f) else Color.Transparent,modifier=Modifier.fillMaxWidth().clickable{setSelected(p);open=false;query=""}){Text(p.name,Modifier.padding(12.dp),fontWeight=if(p.id==selected.id)FontWeight.Bold else FontWeight.Normal)}}}},confirmButton={},dismissButton={TextButton({open=false}){Text("Cerrar")}})}}
@Composable private fun Work(a:String,sa:(String)->Unit,b:String,sb:(String)->Unit,c:String,sc:(String)->Unit,next:()->Unit){Column(Modifier.padding(24.dp)){Header("Paso 4 de 8","Tu actividad diaria");Text("Queremos medir tu día real, no asignarte una etiqueta genérica.",color=TitanTextSecondary);Field("Horas de pie",a,sa);Field("Horas en movimiento",b,sb);Field("Horas con cargas / trabajo físico",c,sc);Spacer(Modifier.weight(1f));PrimaryButton("Continuar",next)}}
@Composable private fun WorkDetail(breaks:String,setBreaks:(String)->Unit,intensity:WorkIntensity,setIntensity:(WorkIntensity)->Unit,variable:Boolean,setVariable:(Boolean)->Unit,next:()->Unit){Column(Modifier.padding(24.dp)){Header("Paso 5 de 8","Cómo es tu jornada");Field("Horas totales de pausas",breaks,setBreaks);Text("Intensidad habitual",color=TitanTextSecondary);Row{WorkIntensity.entries.forEach{v->FilterChip(intensity==v,{setIntensity(v)},{Text(when(v){WorkIntensity.LOW->"Baja";WorkIntensity.MODERATE->"Media";WorkIntensity.HIGH->"Alta"})});Spacer(Modifier.width(6.dp))}};Spacer(Modifier.height(12.dp));Text("¿Tu actividad cambia mucho de un día a otro?",color=TitanTextSecondary);Row{FilterChip(variable,{setVariable(true)},{Text("Sí")});Spacer(Modifier.width(8.dp));FilterChip(!variable,{setVariable(false)},{Text("No")})};Spacer(Modifier.weight(1f));PrimaryButton("Continuar",next)}}
@Composable private fun Training(a:String,sa:(String)->Unit,b:String,sb:(String)->Unit,intensity:TrainingIntensity,setIntensity:(TrainingIntensity)->Unit,next:()->Unit){Column(Modifier.padding(24.dp)){Header("Paso 6 de 8","Tu entrenamiento");Text("Frecuencia, duración e intensidad alimentan la estimación inicial.",color=TitanTextSecondary);Field("Sesiones por semana",a,sa);Field("Minutos por sesión",b,sb);Text("Intensidad habitual",color=TitanTextSecondary);Row{TrainingIntensity.entries.forEach{v->FilterChip(intensity==v,{setIntensity(v)},{Text(when(v){TrainingIntensity.LIGHT->"Suave";TrainingIntensity.MODERATE->"Media";TrainingIntensity.HIGH->"Alta"})});Spacer(Modifier.width(6.dp))}};Spacer(Modifier.weight(1f));PrimaryButton("Calcular mantenimiento",next)}}
private fun mealNamesForCount(count:Int):List<String> = when(count.coerceIn(2,6)){2->listOf("Comida","Cena");3->listOf("Desayuno","Comida","Cena");4->listOf("Desayuno","Comida","Merienda","Cena");5->listOf("Desayuno","Media mañana","Comida","Merienda","Cena");else->listOf("Desayuno","Media mañana","Comida","Merienda","Cena","Recena")}
@Composable private fun MealCountQuestion(count:Int,setCount:(Int)->Unit,next:()->Unit){Column(Modifier.padding(24.dp)){Header("Paso 7 de 8","¿Cuántas comidas haces al día?");Text("TITÁN organizará tu plan alrededor de tu rutina habitual.",color=TitanTextSecondary);Spacer(Modifier.height(18.dp));(2..6).forEach{n->Card(onClick={setCount(n)},modifier=Modifier.fillMaxWidth().padding(vertical=5.dp),shape=RoundedCornerShape(18.dp),colors=CardDefaults.cardColors(containerColor=if(count==n)TitanPrimary.copy(alpha=.13f) else TitanCard),border=if(count==n)androidx.compose.foundation.BorderStroke(1.dp,TitanPrimary) else null){Row(Modifier.fillMaxWidth().padding(18.dp),verticalAlignment=Alignment.CenterVertically){Text("$n comidas",Modifier.weight(1f),fontWeight=FontWeight.Bold);Text(if(count==n)"✓" else "○",color=if(count==n)TitanPrimary else TitanTextSecondary,fontSize=22.sp)}}};Spacer(Modifier.weight(1f));PrimaryButton("Continuar",next)}}
@Composable private fun Maintenance(e:EnergyEstimate,next:()->Unit){var details by remember{mutableStateOf(false)};Column(Modifier.padding(horizontal=22.dp)){Header("Paso 8 de 8","Tu mantenimiento");Text("Según tus datos, tu gasto energético diario estimado es:",color=TitanTextSecondary);Spacer(Modifier.height(16.dp));Card(colors=CardDefaults.cardColors(containerColor=TitanCard),shape=RoundedCornerShape(22.dp)){Column(Modifier.fillMaxWidth().padding(22.dp)){Text(e.maintenance.toString()+" kcal",fontSize=38.sp,fontWeight=FontWeight.Bold);Text("VER CÓMO SE CALCULÓ "+if(details)"⌃" else "›",color=TitanPrimary,fontWeight=FontWeight.Bold,modifier=Modifier.clickable{details=!details}.padding(vertical=8.dp));AnimatedVisibility(details){Column{Text("GASTO BASAL  "+e.bmr+" kcal",color=TitanTextSecondary);Text("ACTIVIDAD BASE  "+e.baseWithActivity+" kcal",color=TitanTextSecondary);Text("TRABAJO  "+e.dailyActivityKcal+" kcal",color=TitanTextSecondary);Text("ENTRENAMIENTO  "+e.trainingKcal+" kcal",color=TitanTextSecondary)}}}};Spacer(Modifier.weight(1f));PrimaryButton("Elegir estrategia",next)}}
